export const envelope = [56, 38, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;
  const cx = 27.5;
  const cz = 27.5;

  // Block ID Constants
  const ID_AIR = 0;
  const ID_CRYING_OBSIDIAN = 1;
  const ID_OBSIDIAN = 2;
  const ID_POLISHED_BLACKSTONE = 3;
  const ID_POLISHED_BLACKSTONE_BRICKS = 4;
  const ID_SCULK = 5;
  const ID_SCULK_CATALYST = 6;
  const ID_WARPED_HYPHAE = 7;
  const ID_STRIPPED_WARPED_STEM = 8;
  const ID_SEA_LANTERN = 9;
  const ID_CYAN_STAINED_GLASS = 10;
  const ID_TINTED_GLASS = 11;
  const ID_DARK_PRISMARINE = 12;
  const ID_GILDED_BLACKSTONE = 13;
  const ID_BEACON = 14;
  const ID_END_ROD = 15;
  const ID_SCULK_SENSOR = 16;
  const ID_OCHRE_FROGLIGHT = 17;
  const ID_POLISHED_BLACKSTONE_WALL = 18;
  const ID_PURPLE_STAINED_GLASS = 19;

  const palette = [
    "",
    "minecraft:crying_obsidian",
    "minecraft:obsidian",
    "minecraft:polished_blackstone",
    "minecraft:polished_blackstone_bricks",
    "minecraft:sculk",
    "minecraft:sculk_catalyst",
    "minecraft:warped_hyphae",
    "minecraft:stripped_warped_stem",
    "minecraft:sea_lantern",
    "minecraft:cyan_stained_glass",
    "minecraft:tinted_glass",
    "minecraft:dark_prismarine",
    "minecraft:gilded_blackstone",
    "minecraft:beacon",
    "minecraft:end_rod",
    "minecraft:sculk_sensor",
    "minecraft:ochre_froglight",
    "minecraft:polished_blackstone_wall",
    "minecraft:purple_stained_glass"
  ];

  // 3D Voxel Buffer
  const grid = new Uint8Array(W * H * D);
  const getIdx = (x, y, z) => (x * H + y) * D + z;

  const setBlock = (x, y, z, id) => {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid[getIdx(x, y, z)] = id;
  };

  const getBlock = (x, y, z) => {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return ID_AIR;
    return grid[getIdx(x, y, z)];
  };

  // -------------------------------------------------------------
  // 1. MAIN MONOLITHIC SAUCER HULL (Ventral, Equatorial Rim, Dorsal)
  // -------------------------------------------------------------
  for (let y = 13; y <= 31; y++) {
    let rOuter = 0;
    let rInner = 0;

    if (y <= 18) {
      // Ventral underbelly expanding upward
      const t = (y - 13) / 5;
      rOuter = 9.5 + t * 16.5;
      rInner = (y < 17) ? Math.max(0, 4.5 - t * 3.5) : 0;
    } else if (y <= 20) {
      // Equatorial trench
      rOuter = (y === 19) ? 24.5 : 25.8;
      rInner = 0;
    } else if (y <= 27) {
      // Dorsal armor terraces sloping up to dome
      const t = (y - 20) / 7;
      rOuter = 25.5 * (1 - t * 0.82);
      rInner = 0;
    } else {
      // Superstructure base
      const t = (y - 27) / 4;
      rOuter = 4.5 * (1 - t * 0.6);
      rInner = 0;
    }

    const rOuterSq = rOuter * rOuter;
    const rInnerSq = rInner * rInner;

    const xMin = Math.max(0, Math.floor(cx - rOuter - 1));
    const xMax = Math.min(W - 1, Math.ceil(cx + rOuter + 1));
    const zMin = Math.max(0, Math.floor(cz - rOuter - 1));
    const zMax = Math.min(D - 1, Math.ceil(cz + rOuter + 1));

    for (let x = xMin; x <= xMax; x++) {
      for (let z = zMin; z <= zMax; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const distSq = dx * dx + dz * dz;

        if (distSq <= rOuterSq && distSq >= rInnerSq) {
          const dist = Math.sqrt(distSq);
          const angle = Math.atan2(dz, dx);
          const isShell = dist >= rOuter - 1.2;
          const ribDist = Math.abs(Math.sin(angle * 6)); // 12 radial carapace ridges

          let blockId = ID_POLISHED_BLACKSTONE;

          if (y === 19) {
            // Equatorial glowing conduit trench
            blockId = (dist >= rOuter - 1.1) ? ID_SEA_LANTERN : ID_CRYING_OBSIDIAN;
          } else if (y === 17) {
            // Bridge deck floor plate
            if (distSq <= 12 * 12) {
              blockId = ((x + z) % 4 === 0) ? ID_CRYING_OBSIDIAN : ID_POLISHED_BLACKSTONE_BRICKS;
            } else {
              blockId = ID_POLISHED_BLACKSTONE;
            }
          } else if (isShell) {
            if (ribDist < 0.16) {
              blockId = ID_OBSIDIAN;
            } else if (ribDist < 0.32) {
              blockId = ID_CRYING_OBSIDIAN;
            } else if ((x + y + z) % 5 === 0) {
              blockId = ID_SCULK;
            } else if ((x + z) % 7 === 0) {
              blockId = ID_GILDED_BLACKSTONE;
            } else {
              blockId = ID_POLISHED_BLACKSTONE;
            }
          } else if (y >= 18 && y <= 23 && dist <= 9) {
            blockId = ID_POLISHED_BLACKSTONE;
          } else {
            blockId = ID_OBSIDIAN;
          }

          setBlock(x, y, z, blockId);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. COMMAND BIO-DOME & QUANTUM SPIRE (Y: 27 to 36)
  // -------------------------------------------------------------
  for (let y = 27; y <= 31; y++) {
    const rDome = 4.2 - (y - 27) * 0.8;
    for (let x = Math.floor(cx - rDome); x <= Math.ceil(cx + rDome); x++) {
      for (let z = Math.floor(cz - rDome); z <= Math.ceil(cz + rDome); z++) {
        const dist = Math.hypot(x - cx, z - cz);
        if (dist <= rDome) {
          if (dist >= rDome - 0.9) {
            setBlock(x, y, z, ID_TINTED_GLASS);
          } else if (dist <= 1.2) {
            setBlock(x, y, z, ID_SEA_LANTERN);
          }
        }
      }
    }
  }

  // Spire crown & emitter array
  for (let dx = 27; dx <= 28; dx++) {
    for (let dz = 27; dz <= 28; dz++) {
      setBlock(dx, 32, dz, ID_CRYING_OBSIDIAN);
      setBlock(dx, 33, dz, ID_POLISHED_BLACKSTONE_WALL);
    }
  }
  setBlock(27, 34, 27, ID_END_ROD);
  setBlock(28, 34, 28, ID_END_ROD);
  setBlock(27, 35, 28, ID_END_ROD);
  setBlock(28, 35, 27, ID_END_ROD);
  setBlock(27, 36, 27, ID_END_ROD);
  setBlock(28, 36, 28, ID_END_ROD);

  // -------------------------------------------------------------
  // 3. FORWARD ANNIHILATOR CANNON & MANDIBLES (Facing North: -Z)
  // -------------------------------------------------------------
  // Annihilator Cannon Core & Barrel
  for (let z = 6; z <= 24; z++) {
    const t = (z - 6) / 18;
    const rCannon = 2.7 + t * 0.8;
    for (let x = Math.floor(cx - rCannon); x <= Math.ceil(cx + rCannon); x++) {
      for (let y = Math.floor(19 - rCannon); y <= Math.ceil(19 + rCannon); y++) {
        const dist = Math.hypot(x - cx, y - 19);
        if (dist <= rCannon) {
          if (dist <= 1.2) {
            if (z === 6 || z % 4 === 0) {
              setBlock(x, y, z, ID_SEA_LANTERN);
            } else {
              setBlock(x, y, z, ID_CYAN_STAINED_GLASS);
            }
          } else if (dist >= rCannon - 0.9) {
            if (z === 6 || z === 10 || z === 16) {
              setBlock(x, y, z, ID_CRYING_OBSIDIAN);
            } else {
              setBlock(x, y, z, ID_POLISHED_BLACKSTONE_BRICKS);
            }
          }
        }
      }
    }
  }

  // Plasma Emitter Needles at Muzzle
  setBlock(Math.floor(cx) - 2, 19, 5, ID_END_ROD);
  setBlock(Math.ceil(cx) + 2, 19, 5, ID_END_ROD);
  setBlock(27, 21, 5, ID_END_ROD);
  setBlock(28, 17, 5, ID_END_ROD);

  // Left & Right Bio-Mechanical Mandibles
  const buildMandible = (sideSign) => {
    for (let step = 0; step <= 32; step++) {
      const t = step / 32;
      const p0x = cx + sideSign * 20, p0y = 19, p0z = 24;
      const p1x = cx + sideSign * 23, p1y = 20, p1z = 13;
      const p2x = cx + sideSign * 8,  p2y = 19, p2z = 4;

      const mx = (1 - t) * (1 - t) * p0x + 2 * (1 - t) * t * p1x + t * t * p2x;
      const my = (1 - t) * (1 - t) * p0y + 2 * (1 - t) * t * p1y + t * t * p2y;
      const mz = (1 - t) * (1 - t) * p0z + 2 * (1 - t) * t * p1z + t * t * p2z;

      const thick = 1.9 * (1 - t * 0.45);

      for (let x = Math.floor(mx - thick); x <= Math.ceil(mx + thick); x++) {
        for (let y = Math.floor(my - thick); y <= Math.ceil(my + thick); y++) {
          for (let z = Math.floor(mz - thick); z <= Math.ceil(mz + thick); z++) {
            const d = Math.hypot(x - mx, y - my, z - mz);
            if (d <= thick) {
              const blk = (d < thick - 0.7) ? ID_CRYING_OBSIDIAN : ID_POLISHED_BLACKSTONE_BRICKS;
              setBlock(x, y, z, blk);
            }
          }
        }
      }

      // External Carapace Spines
      if (step % 5 === 0 && step < 28) {
        const spineX = Math.round(mx + sideSign * (thick + 0.5));
        const spineY = Math.round(my + 1);
        const spineZ = Math.round(mz);
        setBlock(spineX, spineY, spineZ, ID_POLISHED_BLACKSTONE_WALL);
      }
    }
  };
  buildMandible(-1);
  buildMandible(1);

  // -------------------------------------------------------------
  // 4. REAR WARP ENGINES & THRUSTERS (South: +Z)
  // -------------------------------------------------------------
  const thrusters = [
    { angle: Math.PI * 0.5, r: 24.5, size: 3.2 },
    { angle: Math.PI * 0.5 - 0.65, r: 23.5, size: 2.7 },
    { angle: Math.PI * 0.5 + 0.65, r: 23.5, size: 2.7 }
  ];

  for (const th of thrusters) {
    const tx = cx + Math.cos(th.angle) * th.r;
    const tz = cz + Math.sin(th.angle) * th.r;
    const ty = 19;

    for (let zOff = -2; zOff <= 3; zOff++) {
      const pz = Math.round(tz + zOff);
      const rad = th.size;
      for (let x = Math.floor(tx - rad); x <= Math.ceil(tx + rad); x++) {
        for (let y = Math.floor(ty - rad); y <= Math.ceil(ty + rad); y++) {
          const d = Math.hypot(x - tx, y - ty);
          if (d <= rad) {
            if (d <= 1.2) {
              if (zOff >= 2) {
                setBlock(x, y, pz, ID_PURPLE_STAINED_GLASS);
              } else if (zOff === 1) {
                setBlock(x, y, pz, ID_SEA_LANTERN);
              } else {
                setBlock(x, y, pz, ID_CRYING_OBSIDIAN);
              }
            } else if (d >= rad - 0.8) {
              setBlock(x, y, pz, ID_DARK_PRISMARINE);
            } else {
              setBlock(x, y, pz, ID_POLISHED_BLACKSTONE);
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 5. CENTRAL SIPHON BEAM & GROUND CORRUPTION CRATER
  // -------------------------------------------------------------
  const beamRadius = 6.5;
  for (let x = Math.floor(cx - beamRadius); x <= Math.ceil(cx + beamRadius); x++) {
    for (let z = Math.floor(cz - beamRadius); z <= Math.ceil(cz + beamRadius); z++) {
      const dist = Math.hypot(x - cx, z - cz);
      if (dist > beamRadius) continue;

      const rawH = api.heightAt(x, z);
      const gh = Math.max(0, Math.min(seatY + 5, Math.round(seatY + rawH)));

      // Ground crater and corruption foundation
      for (let y = 0; y <= gh; y++) {
        let blk = ID_POLISHED_BLACKSTONE;
        if (y === gh) {
          if (dist <= 2.2) {
            blk = ID_SEA_LANTERN;
          } else if (dist <= 4.2) {
            blk = ((x + z) % 2 === 0) ? ID_CRYING_OBSIDIAN : ID_SCULK_CATALYST;
          } else {
            blk = ID_SCULK;
          }
        } else if (y >= gh - 1) {
          blk = ID_CRYING_OBSIDIAN;
        }
        setBlock(x, y, z, blk);
      }

      // Siphon tractor beam rising to ventral hull
      for (let y = gh + 1; y <= 16; y++) {
        if (dist <= 1.5) {
          if (x === Math.floor(cx) && z === Math.floor(cz)) {
            if (y === gh + 1) {
              setBlock(x, y, z, ID_BEACON);
            } else if (y % 4 === 0) {
              setBlock(x, y, z, ID_SEA_LANTERN);
            } else {
              setBlock(x, y, z, ID_CYAN_STAINED_GLASS);
            }
          } else {
            setBlock(x, y, z, ID_CYAN_STAINED_GLASS);
          }
        } else if (dist <= 2.8) {
          const angle = Math.atan2(z - cz, x - cx);
          const helix = Math.sin(y * 0.8 + angle * 2);
          if (helix > 0.5) {
            setBlock(x, y, z, ID_CRYING_OBSIDIAN);
          } else if (helix < -0.6) {
            setBlock(x, y, z, ID_TINTED_GLASS);
          }
        } else if (dist >= 3.8 && dist <= 5.0) {
          if (y === 8 || y === 12 || y === 15) {
            setBlock(x, y, z, ID_POLISHED_BLACKSTONE_BRICKS);
          } else if ((y === 9 || y === 13) && dist >= 4.4) {
            setBlock(x, y, z, ID_SCULK_SENSOR);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 6. SIX BIOMECHANICAL TENDRIL LIMBS (GROUND ROOTS)
  // -------------------------------------------------------------
  const legAngles = [0.60, 1.57, 2.54, 3.74, 4.71, 5.68];

  for (const angle of legAngles) {
    const footR = 21.5;
    const footX = cx + Math.cos(angle) * footR;
    const footZ = cz + Math.sin(angle) * footR;
    const rawFootH = api.heightAt(Math.round(footX), Math.round(footZ));
    const footGh = Math.max(0, Math.min(seatY + 5, Math.round(seatY + rawFootH)));

    const p0x = cx + Math.cos(angle) * 18.0;
    const p0y = 19;
    const p0z = cz + Math.sin(angle) * 18.0;

    const p1x = cx + Math.cos(angle + 0.08) * 24.5;
    const p1y = 22;
    const p1z = cz + Math.sin(angle + 0.08) * 24.5;

    const p2x = cx + Math.cos(angle - 0.05) * 23.0;
    const p2y = Math.max(footGh + 4, 10);
    const p2z = cz + Math.sin(angle - 0.05) * 23.0;

    const p3x = footX;
    const p3y = footGh + 1;
    const p3z = footZ;

    const steps = 35;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const u = 1 - t;

      const lx = u * u * u * p0x + 3 * u * u * t * p1x + 3 * u * t * t * p2x + t * t * t * p3x;
      const ly = u * u * u * p0y + 3 * u * u * t * p1y + 3 * u * t * t * p2y + t * t * t * p3y;
      const lz = u * u * u * p0z + 3 * u * u * t * p1z + 3 * u * t * t * p2z + t * t * t * p3z;

      const thick = 2.0 - t * 0.7;

      for (let x = Math.floor(lx - thick); x <= Math.ceil(lx + thick); x++) {
        for (let y = Math.floor(ly - thick); y <= Math.ceil(ly + thick); y++) {
          for (let z = Math.floor(lz - thick); z <= Math.ceil(lz + thick); z++) {
            const d = Math.hypot(x - lx, y - ly, z - lz);
            if (d <= thick) {
              let blk = ID_POLISHED_BLACKSTONE_BRICKS;
              if (d <= thick - 0.8) {
                blk = (s % 6 === 0) ? ID_OCHRE_FROGLIGHT : ID_CRYING_OBSIDIAN;
              } else if ((x + y + z) % 4 === 0) {
                blk = ID_WARPED_HYPHAE;
              } else if ((x + z) % 3 === 0) {
                blk = ID_SCULK;
              }
              setBlock(x, y, z, blk);
            }
          }
        }
      }
    }

    // Foot Claw Talons & Ground Rooting Foundation
    for (const cAngleOffset of [-0.35, 0, 0.35]) {
      const clawAngle = angle + cAngleOffset;
      for (let cDist = 0; cDist <= 3.5; cDist += 0.8) {
        const clawX = Math.round(footX + Math.cos(clawAngle) * cDist);
        const clawZ = Math.round(footZ + Math.sin(clawAngle) * cDist);
        if (clawX < 0 || clawX >= W || clawZ < 0 || clawZ >= D) continue;

        const cGh = Math.max(0, Math.min(seatY + 5, Math.round(seatY + api.heightAt(clawX, clawZ))));

        for (let y = 0; y <= Math.max(footGh + 2, cGh + 1); y++) {
          if (y <= cGh) {
            const blk = (y === cGh) ? ID_SCULK_CATALYST : ID_CRYING_OBSIDIAN;
            setBlock(clawX, y, clawZ, blk);
          } else if (y <= footGh + 1) {
            setBlock(clawX, y, clawZ, ID_POLISHED_BLACKSTONE_BRICKS);
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 7. HOLLOW INTERIOR COMMAND BRIDGE
  // -------------------------------------------------------------
  for (let x = 24; x <= 31; x++) {
    for (let y = 18; y <= 23; y++) {
      for (let z = 24; z <= 31; z++) {
        setBlock(x, y, z, ID_AIR);
      }
    }
  }

  // Ensure solid floor and ceiling around the interior
  for (let x = 24; x <= 31; x++) {
    for (let z = 24; z <= 31; z++) {
      if (getBlock(x, 17, z) === ID_AIR) {
        setBlock(x, 17, z, ID_POLISHED_BLACKSTONE_BRICKS);
      }
      if (getBlock(x, 24, z) === ID_AIR) {
        setBlock(x, 24, z, ID_OBSIDIAN);
      }
    }
  }

  // -------------------------------------------------------------
  // 8. EMIT BLOCKS TO API
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const id = grid[getIdx(x, y, z)];
        if (id > 0) {
          api.set(x, y, z, palette[id]);
        }
      }
    }
  }

  return {
    name: "Alien Mothership",
    seatY: seatY,
    anchors: {
      front: [28, 19, 2],
      door: [28, seatY, 28],
      core: [28, 19, 28]
    },
    interiors: [
      {
        min: [24, 18, 24],
        max: [31, 23, 31],
        kind: "bridge"
      }
    ]
  };
}

