export const envelope = [20, 14, 20];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function setGrid(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  const stonePrimary = api.theme?.stone?.primary || "minecraft:cobblestone";
  const groundPavement = api.theme?.ground?.pavement || "minecraft:gravel";

  // Saucer center and orientation parameters:
  // Saucer is tilted nose-down into the turf towards local North (-Z)
  // with a slight starboard bank (+X).
  const Cx = 10.0;
  const Cy = 5.5;
  const Cz = 10.0;
  const R_hull = 7.2;

  // Normal vector of the saucer disc plane (perpendicular to hull)
  const Nx_raw = 0.16;
  const Ny_raw = 0.92;
  const Nz_raw = -0.36;
  const nLen = Math.hypot(Nx_raw, Ny_raw, Nz_raw);
  const Nx = Nx_raw / nLen;
  const Ny = Ny_raw / nLen;
  const Nz = Nz_raw / nLen;

  // -------------------------------------------------------------
  // PASS 1: Impact Trench & Ejecta Berms (Furrow leading from North)
  // -------------------------------------------------------------
  for (let z = 0; z <= 9; z++) {
    const fCenter = 10.0 + (z - 8) * 0.12;
    const fHalfWidth = 2.0 + (z / 8.0) * 1.8;
    const minX = Math.max(1, Math.floor(fCenter - fHalfWidth - 1.5));
    const maxX = Math.min(W - 2, Math.ceil(fCenter + fHalfWidth + 1.5));

    for (let x = minX; x <= maxX; x++) {
      const distF = Math.abs(x - fCenter);

      // Trench bed at seat plane y = 2
      if (distF <= fHalfWidth) {
        const rVal = api.random();
        let floorBlock = "minecraft:coarse_dirt";
        if (rVal < 0.35) floorBlock = "minecraft:packed_mud";
        else if (rVal < 0.6) floorBlock = "minecraft:mud";
        else if (rVal < 0.8) floorBlock = groundPavement;
        else floorBlock = "minecraft:rooted_dirt";

        // Near the impact point (z=6..9), scorch and vitrify the soil
        if (z >= 6 && distF <= 1.8) {
          const scorchVal = api.random();
          if (scorchVal < 0.3) floorBlock = "minecraft:magma_block";
          else if (scorchVal < 0.6) floorBlock = "minecraft:crying_obsidian";
          else if (scorchVal < 0.85) floorBlock = "minecraft:polished_blackstone";
        }
        setGrid(x, 2, z, floorBlock);
      }

      // Ejecta berms / churned earth ridges along trench sides
      if (distF > fHalfWidth - 0.7 && distF <= fHalfWidth + 1.5) {
        let bermTopY = 3;
        if (z >= 5 && z <= 8 && distF <= fHalfWidth + 0.6) {
          bermTopY = 4;
        }
        for (let y = 2; y <= bermTopY; y++) {
          const rBerm = api.random();
          let bermBlock = "minecraft:coarse_dirt";
          if (rBerm < 0.3) bermBlock = "minecraft:packed_mud";
          else if (rBerm < 0.55) bermBlock = stonePrimary;
          else if (rBerm < 0.75) bermBlock = "minecraft:cobblestone";
          else bermBlock = "minecraft:rooted_dirt";

          if (y === 4 && api.random() < 0.4) {
            bermBlock = "minecraft:polished_deepslate";
          }
          setGrid(x, y, z, bermBlock);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // PASS 2: Metallic Saucer Hull & Cockpit Dome
  // -------------------------------------------------------------
  for (let x = 1; x < W - 1; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 1; z < D - 1; z++) {
        const dx = (x + 0.5) - Cx;
        const dy = (y + 0.5) - Cy;
        const dz = (z + 0.5) - Cz;

        const h = dx * Nx + dy * Ny + dz * Nz;
        const px = dx - h * Nx;
        const py = dy - h * Ny;
        const pz = dz - h * Nz;
        const r = Math.hypot(px, py, pz);

        if (r > R_hull) continue;

        // Profile thickness equations
        const rNorm = r / R_hull;
        const tHull = 1.18 * Math.sqrt(Math.max(0, 1.0 - rNorm * rNorm)) + 0.28;
        const tDome = (r < 3.3) ? (1.25 * Math.sqrt(Math.max(0, 1.0 - (r / 3.3) ** 2))) : 0;
        const tVentral = (r < 3.0) ? (0.85 * Math.sqrt(Math.max(0, 1.0 - (r / 3.0) ** 2))) : 0;

        const maxH = tHull + tDome;
        const minH = -(tHull + tVentral);

        if (h < minH || h > maxH) continue;

        const angle = Math.atan2(px, pz);
        const distFromTop = maxH - h;
        const distFromBot = h - minH;

        // Damaged / ruptured hull quadrant on the forward-port flank
        const inDamageZone = (dx >= -5.2 && dx <= -0.8 && dz >= -5.5 && dz <= -1.2 && y <= 6);

        if (inDamageZone) {
          // Sheared open cavity
          if (distFromTop < 0.9 && r > 2.5 && api.random() < 0.65) {
            continue;
          }
          // Buckled alloy shards and glowing conduits
          const rDmg = api.random();
          if (rDmg < 0.3) {
            setGrid(x, y, z, "minecraft:crying_obsidian");
          } else if (rDmg < 0.5) {
            setGrid(x, y, z, "minecraft:magma_block");
          } else if (rDmg < 0.7) {
            setGrid(x, y, z, "minecraft:dark_prismarine");
          } else if (rDmg < 0.85) {
            setGrid(x, y, z, "minecraft:iron_bars");
          } else {
            setGrid(x, y, z, "minecraft:polished_blackstone");
          }
          continue;
        }

        // 1. Cockpit Dome (Dorsal Center)
        if (r < 3.3 && h > tHull - 0.25) {
          // Internal alien navigation core
          if (r < 1.4 && h > 0.4 && h < 1.6) {
            setGrid(x, y, z, (h > 0.8) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian");
            continue;
          }
          // Outer canopy glass & structural ribs
          if (distFromTop < 0.85) {
            const isStrut = Math.abs(px) < 0.35 || Math.abs(pz) < 0.35;
            if (isStrut) {
              setGrid(x, y, z, "minecraft:polished_blackstone");
            } else {
              setGrid(x, y, z, "minecraft:tinted_glass");
            }
          } else {
            setGrid(x, y, z, "minecraft:dark_prismarine");
          }
          continue;
        }

        // 2. Equatorial Hull Perimeter Rim (r >= 6.3)
        if (r >= 6.3) {
          const angleNorm = ((angle + Math.PI * 2) % (Math.PI / 3)) - (Math.PI / 6);
          if (Math.abs(angleNorm) < 0.22 && Math.abs(h) < 0.5) {
            setGrid(x, y, z, "minecraft:sea_lantern");
          } else if (Math.abs(h) < 0.4) {
            setGrid(x, y, z, "minecraft:crying_obsidian");
          } else {
            setGrid(x, y, z, "minecraft:polished_blackstone");
          }
          continue;
        }

        // 3. Dorsal Upper Hull Plating (h > 0)
        if (h > 0) {
          if (distFromTop < 0.85) {
            // Concentric paneling & radial grooves
            const octantAngle = ((angle + Math.PI * 2) % (Math.PI / 4)) - (Math.PI / 8);
            const isSeam = Math.abs(octantAngle) < 0.12;

            if (isSeam) {
              setGrid(x, y, z, "minecraft:polished_deepslate");
            } else if (r >= 3.3 && r < 4.8) {
              setGrid(x, y, z, "minecraft:smooth_basalt");
            } else {
              setGrid(x, y, z, "minecraft:iron_block");
            }
          } else {
            setGrid(x, y, z, "minecraft:dark_prismarine");
          }
          continue;
        }

        // 4. Ventral Lower Hull Plating (h <= 0)
        if (distFromBot < 0.85) {
          // Underbelly anti-grav field generator
          if (r < 2.8) {
            if (r < 1.4) {
              setGrid(x, y, z, "minecraft:sea_lantern");
            } else {
              setGrid(x, y, z, "minecraft:crying_obsidian");
            }
          } else {
            const rUnder = api.random();
            if (rUnder < 0.6) {
              setGrid(x, y, z, "minecraft:smooth_basalt");
            } else if (rUnder < 0.85) {
              setGrid(x, y, z, "minecraft:iron_block");
            } else {
              setGrid(x, y, z, "minecraft:polished_deepslate");
            }
          }
        } else {
          setGrid(x, y, z, "minecraft:iron_block");
        }
      }
    }
  }

  // -------------------------------------------------------------
  // PASS 3: Smoking Engine Breach, Plasma Fire & Shards
  // -------------------------------------------------------------
  setGrid(8, 3, 6, "minecraft:campfire[facing=north,lit=true,signal_fire=false]");
  setGrid(8, 2, 6, "minecraft:magma_block");
  setGrid(7, 3, 6, "minecraft:crying_obsidian");
  setGrid(9, 3, 6, "minecraft:iron_bars");
  setGrid(8, 4, 6, "minecraft:air");
  setGrid(8, 5, 6, "minecraft:iron_bars");

  // Sheared hull plate fragments scattered in the furrow
  setGrid(7, 2, 4, "minecraft:iron_block");
  setGrid(7, 3, 4, "minecraft:dark_prismarine");
  setGrid(12, 2, 4, "minecraft:smooth_basalt");
  setGrid(12, 3, 4, "minecraft:polished_blackstone");
  setGrid(10, 3, 3, "minecraft:crying_obsidian");
  setGrid(9, 2, 2, "minecraft:iron_block");

  // -------------------------------------------------------------
  // PASS 4: Terrain Conformance (Rule 6)
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] && grid[x][y][z] !== "minecraft:air") {
          lowestY = y;
          break;
        }
      }

      if (lowestY === -1) continue;

      const groundH = Math.round(api.heightAt(x, z));
      const targetBaseY = Math.max(0, Math.min(H - 1, 2 + groundH));

      // Build foundation skirt down if ground drops away
      if (targetBaseY < lowestY) {
        for (let y = targetBaseY; y < lowestY; y++) {
          if (!grid[x][y][z] || grid[x][y][z] === "minecraft:air") {
            const rFill = api.random();
            grid[x][y][z] = (rFill < 0.5) ? "minecraft:packed_mud" : "minecraft:coarse_dirt";
          }
        }
      }

      // Build up earth if ground rises above seat level
      if (targetBaseY > lowestY && lowestY <= 4) {
        for (let y = lowestY; y <= targetBaseY; y++) {
          if (!grid[x][y][z] || grid[x][y][z] === "minecraft:air") {
            const rFill = api.random();
            grid[x][y][z] = (rFill < 0.5) ? "minecraft:packed_mud" : "minecraft:coarse_dirt";
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // EMIT: Output all placed blocks deterministically
  // -------------------------------------------------------------
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = grid[x][y][z];
        if (block && block !== "minecraft:air") {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "crashed_scout",
    seatY: 2,
    anchors: {
      front: [10, 2, 0],
      impact: [10, 2, 5],
      cockpit: [10, 8, 10]
    }
  };
}

