export const envelope = [11, 14, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 5;
  const cz = 5;
  const seatY = 4;

  // 3D voxel buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => Array(D).fill(null))
  );

  function set(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[ix][iy][iz] = block;
    }
  }

  function get(x, y, z) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid[ix][iy][iz];
    }
    return null;
  }

  // --- Palette Assembly ---
  const stonePrimary = api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:cracked_stone_bricks";
  const groundPav = api.theme.ground?.pavement || "minecraft:cobblestone";

  // Bio-theme variant (cyan sculk vs amber magma/shroom)
  const isCyan = api.random() > 0.35;
  const bioCore = isCyan ? "minecraft:sculk_catalyst" : "minecraft:shroomlight";
  const bioGlow = isCyan ? "minecraft:verdant_froglight" : "minecraft:ochre_froglight";
  const bioGrowth = isCyan ? "minecraft:sculk" : "minecraft:warped_wart_block";
  const bioAccent = isCyan ? "minecraft:warped_wart_block" : "minecraft:nether_wart_block";

  const hullBlocks = [
    "minecraft:polished_blackstone",
    "minecraft:polished_blackstone_bricks",
    "minecraft:cracked_polished_blackstone_bricks",
    "minecraft:crying_obsidian",
    "minecraft:gilded_blackstone"
  ];

  function getHullBlock(y, dist, angle) {
    const r = api.random();
    if (r < 0.22) return "minecraft:crying_obsidian";
    if (r < 0.40) return "minecraft:polished_blackstone_bricks";
    if (r < 0.55) return "minecraft:cracked_polished_blackstone_bricks";
    if (r < 0.70) return "minecraft:gilded_blackstone";
    return "minecraft:polished_blackstone";
  }

  // --- Instance Variations ---
  const tiltX = (api.random() - 0.5) * 0.38;
  const tiltZ = -0.12 - api.random() * 0.28; // Crashing trajectory leaning forward / North
  const podBaseY = 1;
  const podTopY = Math.min(13, seatY + 7 + Math.floor(api.random() * 3)); // 11 to 13
  const numFins = 3 + Math.floor(api.random() * 3); // 3, 4, or 5 stabilizer spikes
  const finRotOffset = api.random() * Math.PI * 2;
  const hatchDoorStyle = Math.floor(api.random() * 3); // 0: ramp, 1: blown flat, 2: wedged shard
  const craterRadius = 4.1 + api.random() * 0.7;

  function podCenterAt(y) {
    return {
      x: cx + tiltX * (y - seatY),
      z: cz + tiltZ * (y - seatY)
    };
  }

  function podRadius(y) {
    const t = (y - podBaseY) / (podTopY - podBaseY);
    if (t < 0 || t > 1.0) return 0;
    if (t < 0.18) return 1.4 + t * 4.5;
    if (t < 0.58) return 2.1 + Math.sin(((t - 0.18) / 0.4) * Math.PI) * 0.6;
    return Math.max(0.6, 2.0 * (1.0 - (t - 0.58) / 0.42) + 0.4);
  }

  // --- 1. Impact Crater & Subterranean Slag Anchor ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const d = Math.hypot(x - cx, z - cz);
      const hGround = seatY + Math.round(api.heightAt(x, z));

      if (d <= craterRadius) {
        // Crater depression inside, raised slag rim outside
        const isInner = d < 2.4;
        const targetSurfaceY = isInner
          ? Math.max(1, hGround - 1)
          : hGround + (d > craterRadius - 1.2 ? 1 : 0);

        // Solid impact foundation down to rock bottom
        const bottomY = Math.max(0, Math.min(hGround - 2, 1));
        for (let y = bottomY; y <= targetSurfaceY; y++) {
          let b = stonePrimary;
          if (y === targetSurfaceY) {
            if (isInner) {
              b = api.random() < 0.4 ? "minecraft:magma_block" : "minecraft:crying_obsidian";
            } else {
              b = api.random() < 0.5 ? "minecraft:smooth_basalt" : groundPav;
            }
          } else {
            b = api.random() < 0.4 ? "minecraft:smooth_basalt" : stoneAccent;
          }
          set(x, y, z, b);
        }
      }
    }
  }

  // --- 2. Main Spiked Pod Hull ---
  for (let y = podBaseY; y <= podTopY; y++) {
    const center = podCenterAt(y);
    const r = podRadius(y);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dist = Math.hypot(x - center.x, z - center.z);
        if (dist <= r) {
          const angle = Math.atan2(z - center.z, x - center.x);
          const isNorthFacing = z < center.z - 0.2;
          const isHatchY = y >= seatY && y <= seatY + 3;

          // Hatch doorway opening on the North (-Z) face
          if (isNorthFacing && isHatchY && dist < r) {
            continue; // Leave open breach
          }

          // Hollow inner stasis cradle
          if (dist < r - 0.95 && y >= seatY && y <= seatY + 2) {
            if (y === seatY && dist < 0.7) {
              set(x, y, z, bioCore); // Exposed glowing power core
            }
            continue;
          }

          // Outer armor shell
          set(x, y, z, getHullBlock(y, dist, angle));
        }
      }
    }
  }

  // --- 3. Kinetic Stabilizer Fins / Radial Spikes ---
  const finAngleStep = (Math.PI * 2) / numFins;
  for (let i = 0; i < numFins; i++) {
    const fAngle = finRotOffset + i * finAngleStep;
    // Don't place a massive fin directly across the hatch entryway
    const angleDiff = Math.abs(fAngle - -Math.PI / 2);
    if (angleDiff < 0.45 || Math.abs(angleDiff - Math.PI * 2) < 0.45) continue;

    const cosA = Math.cos(fAngle);
    const sinA = Math.sin(fAngle);

    for (let step = 1; step <= 4; step++) {
      const finDist = 1.2 + step * 0.65;
      const midCenter = podCenterAt(seatY + 2);
      const fx = midCenter.x + cosA * finDist;
      const fz = midCenter.z + sinA * finDist;

      const topFinY = seatY + 4 - Math.floor(step * 0.9);
      const hGround = seatY + Math.round(api.heightAt(Math.round(fx), Math.round(fz)));
      const botFinY = Math.max(0, Math.min(seatY, hGround));

      for (let y = botFinY; y <= topFinY; y++) {
        if (y === topFinY) {
          set(fx, y, fz, "minecraft:polished_blackstone");
        } else {
          set(fx, y, fz, "minecraft:obsidian");
        }
      }
    }
  }

  // --- 4. Blown Hatch Door Geometry ---
  const frontCenter = podCenterAt(seatY + 1);
  if (hatchDoorStyle === 0) {
    // Ramp blown outward sloping to ground
    for (let step = 1; step <= 3; step++) {
      const doorZ = frontCenter.z - 1.2 - step * 0.75;
      const doorY = seatY + 1 - step;
      for (let dx = -1; dx <= 1; dx++) {
        set(cx + dx * 0.6, doorY, doorZ, "minecraft:polished_blackstone_bricks");
        set(cx + dx * 0.6, doorY - 1, doorZ, "minecraft:smooth_basalt");
      }
    }
  } else if (hatchDoorStyle === 1) {
    // Blown flat onto the impact crater floor
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = 0; dz <= 2; dz++) {
        const doorX = cx + dx;
        const doorZ = cz - 3 - dz;
        const doorY = seatY + Math.round(api.heightAt(doorX, doorZ));
        set(doorX, doorY, doorZ, "minecraft:polished_blackstone_bricks");
        if (api.random() < 0.3) set(doorX, doorY + 1, doorZ, "minecraft:iron_bars");
      }
    }
  } else {
    // Shattered jagged door shard wedged in crater
    set(cx - 1, seatY + 1, cz - 2, "minecraft:polished_blackstone");
    set(cx - 1, seatY + 2, cz - 3, "minecraft:polished_blackstone_bricks");
    set(cx - 1, seatY + 3, cz - 3, "minecraft:crying_obsidian");
    set(cx, seatY, cz - 3, "minecraft:polished_blackstone");
    set(cx + 1, seatY, cz - 3, "minecraft:crying_obsidian");
  }

  // --- 5. Bioluminescent Alien Growth & Creeping Tendrils ---
  const numTendrils = 4 + Math.floor(api.random() * 3);
  for (let t = 0; t < numTendrils; t++) {
    let tx = cx + (api.random() - 0.5) * 2.0;
    let tz = cz + (api.random() - 0.5) * 2.0;
    const tAngle = (t * Math.PI * 2) / numTendrils + (api.random() - 0.5) * 0.6;
    const tLength = 3 + Math.floor(api.random() * 3);

    for (let step = 0; step < tLength; step++) {
      tx += Math.cos(tAngle) * 0.8;
      tz += Math.sin(tAngle) * 0.8;
      const rx = Math.round(tx);
      const rz = Math.round(tz);

      if (rx >= 0 && rx < W && rz >= 0 && rz < D) {
        const hGround = seatY + Math.round(api.heightAt(rx, rz));
        let surfY = hGround;
        while (surfY < H - 1 && get(rx, surfY + 1, rz) !== null) {
          surfY++;
        }

        // Creep over terrain surface
        if (get(rx, surfY, rz) !== null) {
          set(rx, surfY, rz, api.random() < 0.6 ? bioGrowth : bioAccent);
        } else {
          set(rx, surfY, rz, bioGrowth);
        }

        // Bioluminescent glowing cyst nodule
        if (step === tLength - 1 || api.random() < 0.25) {
          set(rx, surfY, rz, bioGlow);
          set(rx, surfY + 1, rz, bioGrowth);
        }
      }
    }
  }

  // --- 6. Apex Spire Probe ---
  const apex = podCenterAt(podTopY);
  const apexX = Math.round(apex.x);
  const apexZ = Math.round(apex.z);
  set(apexX, podTopY, apexZ, "minecraft:crying_obsidian");
  if (podTopY + 1 < H) {
    set(apexX, podTopY + 1, apexZ, "minecraft:iron_bars");
  }

  // --- 7. Ground Conformance & Foundation Pillar Pass (Rule 6) ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestY = -1;
      let highestY = -1;

      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          if (lowestY === -1) lowestY = y;
          highestY = y;
        }
      }

      if (lowestY !== -1) {
        const hGround = seatY + Math.round(api.heightAt(x, z));
        const fillTarget = Math.max(0, Math.min(lowestY, hGround));

        for (let y = fillTarget; y < lowestY; y++) {
          set(x, y, z, api.random() < 0.4 ? "minecraft:smooth_basalt" : stonePrimary);
        }
      }
    }
  }

  // --- 8. Solid Connectivity & Volume Assurance (Rule 9) ---
  // Ensure the central core disk at y=1..3 is completely solid
  for (let dx = -2; dx <= 2; dx++) {
    for (let dz = -2; dz <= 2; dz++) {
      if (dx * dx + dz * dz <= 5) {
        const hGround = seatY + Math.round(api.heightAt(cx + dx, cz + dz));
        const maxFill = Math.max(1, Math.min(seatY, hGround));
        for (let y = 0; y <= maxFill; y++) {
          if (get(cx + dx, y, cz + dz) === null) {
            set(cx + dx, y, cz + dz, stonePrimary);
          }
        }
      }
    }
  }

  // Flush buffer to api
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = grid[x][y][z];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Alien Assault Drop Pod",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0]
    }
  };
}
